// Detect auto-replies and filter them out
const email = $input.first().json;
const subject = (email.subject || '').toLowerCase();
const headers = email.headers || {};

const AUTO_REPLY_PATTERNS = [
  /out of office/i,
  /fora do escrit[oó]rio/i,
  /resposta autom[aá]tica/i,
  /automatic reply/i,
  /delivery (status )?notification/i,
  /undeliverable/i,
  /mail delivery (system|subsystem)/i,
  /n[aã]o entregue/i,
  /vacation/i,
  /auto-?reply/i,
  /ausente/i
];

const isAutoReply = AUTO_REPLY_PATTERNS.some(p => p.test(subject)) ||
  headers['x-auto-response-suppress'] ||
  headers['auto-submitted'] === 'auto-replied';

return [{
  json: {
    from: email.from,
    subject: email.subject,
    body_snippet: (email.text || '').substring(0, 200),
    date: email.date,
    message_id: email.messageId,
    in_reply_to: headers['in-reply-to'],
    is_auto_reply: isAutoReply
  }
}];

// Update lead: pause cadence, set replied status
// Output is FLAT structure for Supabase node compatibility
const reply = $('Parse Reply & Detect Auto-Reply').first().json;
const lead = $input.first().json;

if (!lead || !lead.id) {
  console.log('Unmatched reply from:', reply.from);
  return [{ json: { unmatched: true, from: reply.from, subject: reply.subject } }];
}

return [{
  json: {
    // Flat fields for Update Lead (Replied) Supabase node
    lead_id: lead.id,
    status: 'replied',
    cadence_paused: true,
    emails_replied: (lead.emails_replied || 0) + 1,
    last_replied_at: new Date().toISOString(),
    // Flat fields for Log Reply Interaction Supabase node
    type: 'email_replied',
    channel: 'email',
    metadata: {
      subject: reply.subject,
      snippet: reply.body_snippet,
      message_id: reply.message_id,
      in_reply_to: reply.in_reply_to
    },
    // Extra context for Notify Sales Team
    lead_name: `${lead.first_name} ${lead.last_name || ''}`.trim(),
    company_name: lead.company_name,
    reply_subject: reply.subject,
    reply_snippet: reply.body_snippet,
    reply_date: reply.date
  }
}];
